import csv
from io import StringIO
from pathlib import Path


def export_cell(value):
    # An explicit text prefix avoids relying on spreadsheet quote stripping.
    # This export intentionally changes dangerous values; it is for human review.
    leading = value.lstrip()
    if leading.startswith(("=", "+", "-", "@", "＝", "＋", "－", "＠")) or value.startswith(("\t", "\r", "\n")):
        return "TEXT: " + value
    return value


